namespace HakutaiKagami.Core.Contracts;
public sealed record WorkAbilitySnapshot(int Politics,int Negotiation,long ReadyAt);
public static class AbilityEffects
{
 public const string Policy="five-ability-known-inspection-preparation-negotiated-fee-v1";
 public static bool Enabled(ContractWorld w)=>w.NewGame?.AbilityPolicy==Policy;
 public static WorkAbilitySnapshot? Terms(ContractWorld w,EntityId actor,long at)=>!Enabled(w)?null:new(CharacterDevelopment.EffectiveAt(w,actor,DevelopmentAbility.Politics,at),CharacterDevelopment.EffectiveAt(w,actor,DevelopmentAbility.Negotiation,at),checked(at+1800-12*CharacterDevelopment.EffectiveAt(w,actor,DevelopmentAbility.Politics,at)));
 public static long Fee(BrokerKind kind,bool personal,WorkAbilitySnapshot? a)=>(personal?100:kind==BrokerKind.Letter?30:50)+(a?.Negotiation>=70?10:0);
 public static string Description(WorkAbilitySnapshot? a)=>a==null?"従来の引受条件":$"政務{a.Politics}で買付の段取りを整え、交渉{a.Negotiation}で報酬条件を相談。能力は失敗抽選には使いません。";
 static EntityId DetailId(TaskState t)=>WorldSession.Child("evidence",t.Id,"ability-inspection-detail");
 static EntityId ReportId(TaskState t)=>WorldSession.Child("message",t.Id,"ability-inspection-detail");
 static string Detail(ContractWorld w,TaskState t,long at){string node=NewGameWorld.Node(t.Scope.Value);var roads=BranchRoutes.GraphEdges(w).Where(e=>(e.From==node||e.To==node)&&!NationalRoutes.Sea(e.Id)).ToArray();var damage=RegionalWeather.Observe(w,t.Scope,at,t.Revision+1);return "現地追加点検：接続陸路"+roads.Length+"本・合計"+roads.Sum(e=>e.LengthMm)/1000+"m。"+(damage==null?"被害の詳細は未採録。":$"田畑被害{damage.Fields}・町被害{damage.Town}・城被害{damage.Castle}（観測時点の試作値）。")+"封鎖の原因は未確認。";}
 internal static void RecordInspection(ContractWorld w,TaskState t){if(!Enabled(w)||CharacterDevelopment.EffectiveAt(w,t.Executor,DevelopmentAbility.Intelligence,w.ElapsedSeconds)<70)return;var id=DetailId(t);if(w.Evidence.Any(e=>e.Id==id))return;string claim=Detail(w,t,w.ElapsedSeconds);w.Evidence=[..w.Evidence,new(id,t.Executor,t.Id,claim,w.ElapsedSeconds,w.ElapsedSeconds,null,null)];w.Knowledge=[..w.Knowledge,new(t.Executor,id,w.ElapsedSeconds)];if(t.Issuer!=t.Executor){var input=w.Requests.Single(r=>r.Id==t.RequestId).Intent;var note=ReportId(t);w.Outbox=[..w.Outbox,new(note,t.Id,t.Executor,t.Issuer,"inspection-detail",claim,w.ElapsedSeconds,input.ReportSeconds,false)];w.SealedMessages=[..w.SealedMessages,note];}}
 public static string[] KnownInspection(WorldSession session,EntityId actor)=>session.GetActorView(actor).Evidence.Where(e=>e.Id.Value.Contains("ability-inspection-detail")||e.Message?.Value.Contains("ability-inspection-detail")==true).Select(e=>e.Claim).ToArray();
 internal static void ValidateInspection(ContractWorld w){foreach(var o in w.Outbox.Where(o=>o.Kind=="inspection-detail"))if(!Enabled(w)||!w.Tasks.Any(t=>t.Id==o.Task&&t.Action==ActionKind.Inspect&&t.Execution==ExecutionPhase.Completed&&t.Issuer!=t.Executor&&o.Id==ReportId(t)))throw new InvalidDataException("孤立した追加点検の返報です");foreach(var t in w.Tasks.Where(t=>t.Action==ActionKind.Inspect&&t.Execution==ExecutionPhase.Completed)){long at=t.FinishedAt!.Value;bool detail=Enabled(w)&&CharacterDevelopment.EffectiveAt(w,t.Executor,DevelopmentAbility.Intelligence,at)>=70;var e=w.Evidence.SingleOrDefault(e=>e.Id==DetailId(t));if(!detail){if(e!=null)throw new InvalidDataException("能力版のない追加点検です");continue;}if(e==null||e.Claim!=Detail(w,t,at)||e.Observer!=t.Executor||e.Subject!=t.Id||e.ObservedAt!=at)throw new InvalidDataException("現地追加点検の原本が不一致です");if(t.Issuer!=t.Executor&&!w.Outbox.Any(o=>o.Id==ReportId(t)&&o.Body==e.Claim&&o.Recipient==t.Issuer))throw new InvalidDataException("追加点検の物理返報がありません");}}
}
